#!/usr/bin/env python3
"""The GitHub PRs board: open pull requests from gh, as MenuSprite blocks. Each PR is a clickable row."""
import json
import subprocess
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime, timezone

FIELDS = "number,title,repository,author,updatedAt,isDraft,url"
SHOWN = 6


def search(query):
    done = subprocess.run(["gh", "search", "prs", query, "--state=open", "--limit=50", "--json", FIELDS],
                          capture_output=True, text=True, timeout=25)
    if done.returncode != 0:
        raise RuntimeError((done.stderr.strip().splitlines() or ["gh exited with status %d" % done.returncode])[-1])
    return json.loads(done.stdout)


def plain(text):
    # Board text reads {word} as one of the sprite's values; a PR title never means one.
    return text.replace("{", "{\u200b")


def age(stamp):
    seconds = (datetime.now(timezone.utc) - datetime.fromisoformat(stamp.replace("Z", "+00:00"))).total_seconds()
    for unit, size in (("d", 86400), ("h", 3600), ("m", 60)):
        if seconds >= size:
            return "%d%s" % (seconds // size, unit)
    return "now"


def card(title, prs, empty, author=True):
    rows = [{"stack": [
        {"text": plain(pr["title"]), "lines": 1},
        {"text": " · ".join(part for part in (
            "%s #%d" % (pr["repository"]["nameWithOwner"], pr["number"]),
            pr["author"]["login"] if author else "", age(pr["updatedAt"]), "draft" if pr.get("isDraft") else "") if part),
         "font": "caption", "color": "gray", "lines": 1},
    ], "spacing": 2, "open": pr["url"]} for pr in prs[:SHOWN]]
    if len(prs) > SHOWN:
        rows.append({"text": "and %d more on GitHub" % (len(prs) - SHOWN), "font": "caption", "color": "gray",
                     "open": "https://github.com/pulls"})
    return {"card": rows or [{"text": empty, "font": "caption", "color": "gray"}], "title": "%s · %d" % (title, len(prs))}


try:
    with ThreadPoolExecutor(2) as pool:  # both searches at once: each takes a second or two
        review, mine = pool.map(search, ["--review-requested=@me", "--author=@me"])
except Exception as error:  # gh missing, signed out or offline: say so on the board instead of a bare error
    print(json.dumps([
        {"text": "GitHub did not answer", "font": "headline", "icon": "exclamationmark.triangle"},
        {"text": plain(str(error)), "font": "caption", "color": "gray"},
        {"text": "If you are signed out, run gh auth login in Terminal, then Refresh.", "font": "caption"},
    ]))
    raise SystemExit(0)

print(json.dumps([
    card("Waiting for your review", review, "Nothing is waiting for you."),
    card("Your pull requests", mine, "You have no open pull requests.", author=False),
]))
